sys_ui_action.script:
function doppelTestConnectivity() {
    g_form.clearMessages();
    var ga = new GlideAjax('x_doppe_doppel_t_0.DoppelUIHelper');
    ga.addParam('sysparm_name', 'testConnectionWithValues');
    ga.addParam('sysparm_api_version', g_form.getValue('api_version') || 'v1');
    ga.addParam('sysparm_org_code', g_form.getValue('organisation_code') || '');
    ga.addParam('sysparm_client_id', g_form.getValue('client_id') || '');
    // Send a secret only if the user typed it on this form. Untouched Password2 fields
    // show a masked value, so the server falls back to the stored secret instead.
    var typed = g_scratchpad.doppelTyped || {};
    var secrets = ['api_key', 'user_api_key', 'client_secret'];
    for (var i = 0; i < secrets.length; i++) {
        var v = g_form.getValue(secrets[i]);
        if (typed[secrets[i]] && v) ga.addParam('sysparm_' + secrets[i], v);
    }
    g_form.addInfoMessage('Testing the connection to Doppel...');
    ga.getXMLAnswer(function (answer) {
        g_form.clearMessages();
        var r;
        try { r = JSON.parse(answer); } catch (e) { r = { success: false, message: 'Unexpected response from the server.' }; }
        g_form.setValue('connectivity_verified', r.success ? 'true' : 'false');
        g_form.setValue('last_test_result', (r.success ? 'Success: ' : 'Failed: ') + (r.message || ''));
        if (r.tested_at) g_form.setValue('last_tested', r.tested_at);
        if (r.success) {
            g_form.addInfoMessage((r.message || 'Connected.') + ' Click Update (or Submit) to save.');
        } else {
            g_form.addErrorMessage(r.message || 'Connection failed.');
        }
    });
}
